#include "exotic/cognition/temporal_agency.hpp"
#include <algorithm>
namespace exotic::cognition {
std::vector<TemporalDecision> TemporalAgency::consider(const std::vector<TemporalOption>&options,std::int64_t now)const{std::vector<TemporalDecision> out;for(const auto&o:options){TemporalDecision d;d.intention_id=o.intention.id;if(o.intention.state!="committed"&&o.intention.state!="tentative"&&o.intention.state!="suspended"){d.choice=TemporalChoice::Skip;d.suggested_time=now;d.rationale="Inactive intention can remain in memory without receiving a time slot.";out.push_back(d);continue;}if(o.earliest>now){d.choice=TemporalChoice::Later;d.suggested_time=o.earliest;d.rationale="The intention is available for a future window; waiting does not weaken or commit it.";out.push_back(d);continue;}const bool deadline_expired=o.deadline>0&&o.deadline<now;const bool deadline_close=o.deadline>0&&o.deadline<=now+3600;const bool recurrence_due=o.recurrence_seconds>0&&(o.last_active==0||now-o.last_active>=o.recurrence_seconds);if(deadline_expired){d.choice=TemporalChoice::Review;d.suggested_time=now;d.rationale="The deadline has passed; review whether to resume, revise, abandon, or do nothing instead of assuming execution.";}else if(o.stale_review){d.choice=TemporalChoice::Review;d.suggested_time=now;d.rationale="The intention has gone stale and is due for voluntary reconsideration; review does not alter its state.";}else if(o.interrupted&&o.interruption_cost>=0.55){d.choice=TemporalChoice::Resume;d.suggested_time=now;d.rationale="Resumption is worth considering because context restoration is costly; it remains a scheduling choice.";}else if(deadline_close||o.urgency>=0.75){d.choice=TemporalChoice::Now;d.suggested_time=now;d.rationale="Current timing has high urgency or a nearby deadline; acting now is recommended, not compelled.";}else if(recurrence_due){d.choice=TemporalChoice::Resume;d.suggested_time=now;d.rationale="A recurring interest is due for reconsideration; recurrence creates an opportunity, not an obligation.";}else if(o.delayed_value>0.65&&o.urgency<0.45){d.choice=TemporalChoice::Wait;d.suggested_time=now+900;d.rationale="Delayed value currently outweighs urgency; patience is an available choice.";}else{d.choice=TemporalChoice::Wait;d.suggested_time=now+300;d.rationale="No timing signal is strong enough to justify consuming the current window.";}out.push_back(d);}return out;}
} // namespace exotic::cognition
